def parse_duration(text: str) -> float:
    if not text or not text.startswith('P'):
        raise ValueError("Invalid duration format")

    text = text[1:]  # Remove 'P'

    total_seconds = 0.0
    has_component = False

    # Check for 'T' separator
    if 'T' in text:
        date_part, time_part = text.split('T', 1)
        if not time_part:
            raise ValueError("T must be followed by at least one time component")
    else:
        date_part = text
        time_part = ""

    # Parse date part (weeks or days)
    if date_part:
        if date_part.endswith('W'):
            # Week format: P<n>W
            week_str = date_part[:-1]
            if not week_str or 'D' in date_part:
                raise ValueError("Invalid duration format")
            try:
                weeks = float(week_str.replace(',', '.'))
                if weeks < 0:
                    raise ValueError("Negative durations not allowed")
                total_seconds += weeks * 7 * 86400
                has_component = True
            except ValueError:
                raise ValueError("Invalid duration format")
        elif date_part.endswith('D'):
            # Day format: P<n>D
            day_str = date_part[:-1]
            if not day_str or 'W' in date_part:
                raise ValueError("Invalid duration format")
            try:
                days = float(day_str.replace(',', '.'))
                if days < 0:
                    raise ValueError("Negative durations not allowed")
                total_seconds += days * 86400
                has_component = True
            except ValueError:
                raise ValueError("Invalid duration format")
        elif date_part:
            # Has date part but doesn't end with W or D
            raise ValueError("Invalid duration format")

    # Parse time part (hours, minutes, seconds)
    if time_part:
        i = 0
        time_components = {'H': 3600, 'M': 60, 'S': 1}
        last_component_found = False

        while i < len(time_part):
            # Find the next component letter
            j = i
            while j < len(time_part) and time_part[j] not in 'HMS':
                j += 1

            if j == len(time_part):
                # No more components, but we have remaining text
                if i < len(time_part):
                    raise ValueError("Invalid duration format")
                break

            component_letter = time_part[j]
            value_str = time_part[i:j]

            if not value_str:
                raise ValueError("Invalid duration format")

            try:
                value = float(value_str.replace(',', '.'))
                if value < 0:
                    raise ValueError("Negative durations not allowed")
                total_seconds += value * time_components[component_letter]
                has_component = True
            except ValueError:
                raise ValueError("Invalid duration format")

            i = j + 1

    if not has_component:
        raise ValueError("At least one component must be present")

    return total_seconds
